b:if.b:skin:
    /* ===== AnimeSail ===== */
    :root{ 
      --sl-bg:#111; 
      --sl-pan:#1f1f1f; 
      --sl-kartu:#333; 
      --sl-bd:#2e2e2e; 
      --sl-bir:#209cee; 
      --sl-bir2:#0378c5; 
      --sl-tx:#ccc; 
      --sl-tx2:#fff; 
      --sl-tx3:#8f8f8f; 
    } 
    *{box-sizing:border-box} 
    body{margin:0;background:var(--sl-bg);color:var(--sl-tx); font:14px/1.6 Nunito,-apple-system,"Segoe UI",Roboto,Arial,sans-serif; overflow-x: clip; overflow-y: visible;} 
    a{color:inherit;text-decoration:none} 
    img{max-width:100%;display:block} 
  .sl-wrap {
  max-width: 1120px;
  margin: 0 auto;
  padding: 0 0px;
  padding-top: 4px; /* Jarak atas */
}


    /* bilah atas */ 
    .sl-top{position:sticky;top:0;z-index:60;background:#0a0a0a;border-bottom:1px solid var(--sl-bd)} 
    .sl-top-in{max-width:1120px;margin:0 auto;padding:9px 10px;display:flex;align-items:center;gap:9px} 
    .sl-logo{display:flex;align-items:center;gap:7px;font-size:16px;font-weight:800;color:var(--sl-tx2);white-space:nowrap} 
    .sl-logo svg{width:22px;height:22px;stroke:var(--sl-bir);fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round} 
    .sl-cari-atas{flex:1;min-width:0} 
    .sl-cari-atas input{width:100%;background:var(--sl-pan);border:1px solid var(--sl-bd);border-radius:4px; color:var(--sl-tx2);padding:8px 12px;font:inherit;font-size:13px;outline:none} 
    .sl-cari-atas input:focus{border-color:var(--sl-bir)} 
    .sl-burger{background:transparent;border:0;padding:6px;cursor:pointer} 
    .sl-burger svg{width:22px;height:22px;stroke:var(--sl-tx2);fill:none;stroke-width:2;stroke-linecap:round} 
    .sl-laci {
      display: none;
      flex-direction: column;
      background: var(--sl-pan);
      border-top: 1px solid var(--sl-bd);
      border-bottom: 1px solid var(--sl-bd);
      position: absolute;
      top: 100%; 
      left: 0;
      width: 100%;
      box-shadow: 0 10px 15px rgba(0,0,0,0.5); 
    } 
    .sl-laci.buka { display: flex; }
    .sl-laci a{padding:11px 14px;border-bottom:1px solid var(--sl-bd);font-size:13.5px;color:var(--sl-tx2)} 
    .sl-laci a:hover{background:var(--sl-bir2)} 
        /* panel sambutan */ 
    .sl-sambut{background:var(--sl-pan);border:1px solid var(--sl-bd);border-radius:5px;padding:13px 15px;margin:12px 10px} /* Ubah margin di sini */
    .sl-sambut p{margin:0 0 6px;font-size:12.5px;line-height:1.75} 
    .sl-sambut p:last-child{margin:0} 
    .sl-sambut b{color:var(--sl-bir)} 
    .sl-sambut-kecil{color:var(--sl-tx3);font-size:11.5px!important}


    /* kepala seksi + chip */ 
        /* kepala seksi + chip */ 
    .sl-kepala {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      margin: 18px 0 11px;
      padding: 0 10px; /* Tambahan padding agar sejajar dengan kartu anime */
    }
.sl-kepala-j{margin:0;font-size:15.5px;font-weight:700;color:var(--sl-tx2)} 
    .sl-chip{display:flex;gap:6px} 
    .sl-chip span, .sl-chip a {font-size:11.5px;font-weight:700;padding:5px 11px;border-radius:3px; background:var(--sl-pan);color:var(--sl-tx3);border:1px solid var(--sl-bd); cursor: pointer;} 
    .sl-chip .on{background:var(--sl-bir2);border-color:var(--sl-bir2);color:#fff} 

    /* grid kartu 2 kolom */ 
        /* grid kartu 2 kolom (Default) */ 
    .sl-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0,1fr));
      gap: 11px;
      padding: 0 10px; /* Tambahan padding di kiri dan kanan */
    } 

.sl-kartu{display:block;background:var(--sl-pan);border:1px solid var(--sl-bd);border-radius:5px; overflow:hidden;padding-bottom:8px} 
    .sl-kartu-gb{position:relative;background:var(--sl-kartu)} 
    .sl-kartu-gb img{width:100%;aspect-ratio:3/4;object-fit:cover;height:auto} 
    .sl-kartu:hover{border-color:var(--sl-bir)} 
    .sl-b-eps{position:absolute;left:0;bottom:0;background:var(--sl-bir2);color:#fff; font:700 11px/1 Nunito,Arial;padding:5px 9px;border-radius:0 4px 0 0} 
    .sl-kartu-j{margin:8px 9px 5px;font-size:13px;font-weight:700;color:var(--sl-tx2);line-height:1.35; display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden} 
    .sl-meta{display:flex;flex-wrap:wrap;gap:8px;margin:0 9px;font-size:11px;color:var(--sl-tx3)} 

    /* daftar mendatar "Lagi Rame" */ 
    .sl-daftar{display:grid;grid-template-columns:1fr;gap:9px} 
    .sl-baris{display:grid;grid-template-columns:52px minmax(0,1fr);gap:11px;align-items:center; background:var(--sl-pan);border:1px solid var(--sl-bd);border-radius:5px;padding:9px} 
    .sl-baris:hover{border-color:var(--sl-bir)} 
    .sl-baris img{width:52px;aspect-ratio:3/4;object-fit:cover;border-radius:3px;height:auto} 
    .sl-baris-j{margin:0 0 3px;font-size:12.5px;font-weight:700;color:var(--sl-tx2);line-height:1.35; display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden} 
    .sl-baris-g,.sl-baris-n{margin:0;font-size:11px;color:var(--sl-tx3);line-height:1.55} 

    /* tombol berikutnya */ 
    .sl-next{display:flex;gap:9px;justify-content:center;padding:16px 0 6px} 
    .sl-next a, .sl-next button {background:var(--sl-bir2);border:none;color:#fff;font-weight:700;font-size:12.5px; padding:10px 22px;border-radius:4px;cursor:pointer;} 
    .sl-next a:hover, .sl-next button:hover {filter:brightness(1.1)} 
    /* halaman dalam (Sesuai Screenshot AnimeSail) */ 
    .sl-judul{margin:14px 0 12px;font-size:17px;font-weight:700;color:var(--sl-tx2);line-height:1.4} 
    .sl-sub{margin:20px 0 10px;font-size:14px;font-weight:700;color:var(--sl-tx2); border-left:3px solid var(--sl-bir);padding-left:9px} 


/* ==========================================
   HALAMAN DALAM (SINGLE POST)
   ========================================== */ 
.sl-judul{margin:0 0 16px;font-size:18px;font-weight:700;color:var(--sl-tx2);line-height:1.4} 
.sl-sub{margin:24px 0 12px;font-size:15px;font-weight:700;color:var(--sl-tx2); border-left:3px solid var(--sl-bir);padding-left:10px} 

/* Kotak Info Utama */
.sl-detail{display:grid;grid-template-columns:120px minmax(0,1fr);gap:16px; background:var(--sl-pan);border:1px solid var(--sl-bd);border-radius:5px;padding:16px;margin:0 0 16px} 
.sl-detail-po img{width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:4px;height:auto;margin:0!important;padding:0!important;border:none!important} 

/* List Info Detail */
.sl-detail-info{list-style:none!important;margin:0!important;padding:0!important;font-size:13px} 
.sl-detail-info li{display:flex;gap:12px;padding:8px 0!important;margin:0!important;border-bottom:1px solid var(--sl-bd)} 
.sl-detail-info li:last-child{border-bottom:0;padding-bottom:0!important} 
.sl-detail-info li:first-child{padding-top:0!important}
.sl-detail-info b{flex:0 0 70px;color:var(--sl-tx3);font-weight:400} 
.sl-detail-info span{color:var(--sl-tx2);font-weight:700;word-break:break-word} 

/* --- PEMBARUAN SINOPSIS --- */
.sl-sinopsis {
    margin: 0 0 14px;
    padding: 13px 15px; /* Sedikit dilebarkan kiri-kanannya agar proporsional */
    background: var(--sl-pan);
    border: 1px solid var(--sl-bd); 
    border-radius: 5px;
    font-size: 13px;
    line-height: 1.85; 
    text-align: justify; 
    color: var(--sl-tx); 
    word-wrap: break-word; 
}

/* Mereset dorongan margin atas bawaan browser */
.sl-sinopsis p {
    margin-top: 0; /* Kunci untuk menghilangkan jarak jauh di bagian atas teks */
    margin-bottom: 10px;
}

/* Menghilangkan margin pada paragraf terakhir agar jarak bawah pas */
.sl-sinopsis p:last-child {
    margin-bottom: 0;
}

/* Menghilangkan margin pada paragraf terakhir agar padding kotak tidak bocor */
.sl-sinopsis p:last-child {
    margin-bottom: 0;
}

/* Episode List */
.sl-eplist{background:var(--sl-pan);border:1px solid var(--sl-bd);border-radius:5px; max-height:500px;overflow-y:auto;margin-bottom:16px} 
.sl-ep{display:flex;align-items:center;justify-content:space-between;gap:10px; padding:12px 16px;border-bottom:1px solid var(--sl-bd);font-size:13px;font-weight:600;color:var(--sl-tx2);transition:background 0.2s} 
.sl-ep:last-child{border-bottom:0} 
.sl-ep:hover{background:#262626} 
.sl-ep i{font-style:normal;background:var(--sl-bir2);color:#fff;padding:6px 14px; font-size:12px;font-weight:700;border-radius:4px;transition:filter 0.2s} 
.sl-ep:hover i{filter:brightness(1.15)} 

/* Tag & Genre */
.sl-tag{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 16px} 
.sl-tag a{background:var(--sl-pan);border:1px solid var(--sl-bd);color:var(--sl-tx); padding:7px 12px;font-size:12px;border-radius:4px} 
.sl-tag a:hover,.sl-tag a.on{background:var(--sl-bir2);border-color:var(--sl-bir2);color:#fff} 

/* Player Video Opsional */
.sl-epnum a{min-width:40px;text-align:center;font-weight:700} 
.sl-player{position:relative;width:100%;aspect-ratio:16/9;background:#000; border-radius:5px;overflow:hidden;margin:0 0 12px} 
.sl-player iframe{position:absolute;inset:0;width:100%;height:100%;border:0} 
.sl-navep{display:flex;gap:7px;margin:0 0 8px} 
.sl-navep a{flex:1 1 0;min-width:0;text-align:center;background:var(--sl-pan);border:1px solid var(--sl-bd); color:var(--sl-tx2);padding:10px 7px;font-size:12px;font-weight:700;border-radius:4px; white-space:nowrap;overflow:hidden;text-overflow:ellipsis} 
.sl-navep a.tengah{background:var(--sl-bir2);border-color:var(--sl-bir2);color:#fff} 
.sl-kosong{padding:24px 10px;text-align:center;color:var(--sl-tx3);font-size:13px} 
.sl-cari{display:flex;gap:8px;margin:14px 0} 
.sl-cari input{flex:1;min-width:0;background:var(--sl-pan);border:1px solid var(--sl-bd); color:var(--sl-tx2);padding:10px 12px;font:inherit;font-size:13px;border-radius:4px;outline:none} 
.sl-cari button{background:var(--sl-bir2);border:0;color:#fff;font-weight:700;padding:10px 18px; font-size:13px;border-radius:4px;cursor:pointer;font-family:inherit}


    /* Wadah utama Detail */
    .sl-detail{display:grid;grid-template-columns:110px minmax(0,1fr);gap:15px; background:var(--sl-pan);border:1px solid var(--sl-bd);border-radius:5px;padding:15px;margin:0 0 14px} 
    .sl-detail-po img{width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:4px;display:block;height:auto} 

    /* List Info (Tipe, Status, dll) */
    .sl-detail-info{list-style:none;margin:0;padding:0;font-size:13px} 
    .sl-detail-info li{display:flex;padding:7px 0;border-bottom:1px solid var(--sl-bd)} 

    /* Trik agar baris pertama mepet & sejajar persis dengan ujung atas foto */
    .sl-detail-info li:first-child{padding-top:0} 
    .sl-detail-info li:last-child{border-bottom:0;padding-bottom:0} 

    /* Lebar teks label (Tipe, Durasi) dibuat konsisten */
    .sl-detail-info b{flex:0 0 85px;color:var(--sl-tx3);font-weight:400} 
    .sl-detail-info span{flex:1;color:var(--sl-tx2);font-weight:600;word-break:break-word} 

    /* kaki */ 
    .sl-kaki{background:#0a0a0a;border-top:1px solid var(--sl-bd);margin-top:24px;padding:18px 12px;text-align:center} 
    .sl-kaki-nav{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin:0 0 11px} 
    .sl-kaki-nav a{font-size:12.5px;color:var(--sl-tx)} 
    .sl-kaki-nav a:hover{color:var(--sl-bir)} 
    .sl-kaki-cp{margin:0 auto 6px;max-width:620px;font-size:11px;line-height:1.75;color:var(--sl-tx3)} 

    @media(min-width:760px){ 
      .sl-grid{grid-template-columns:repeat(6,minmax(0,1fr))} 
      .sl-daftar{grid-template-columns:repeat(2,minmax(0,1fr))} 
      .sl-detail{grid-template-columns:180px minmax(0,1fr);gap:18px} 
      .sl-detail-po img{width:180px} 
      .sl-judul{font-size:22px} 
    } 
    /* ================== KOMENTAR ===================== */ 
    .ai-comments{margin:16px 0} 
    .ai-panel{background:rgba(127,127,127,.08);border:1px solid rgba(127,127,127,.22); border-radius:8px;padding:14px;margin:0 0 14px} 
    .ai-head{font-size:16px;font-weight:800;margin:0 0 12px; padding:0 0 10px;border-bottom:1px solid rgba(127,127,127,.22)} 
    .ai-head .dot{opacity:.55;margin:0 6px} 
    .ai-clist{list-style:none;margin:0;padding:0} 
    .ai-clist li{padding:12px 0;border-bottom:1px solid rgba(127,127,127,.18)} 
    .ai-clist li:last-child{border-bottom:0} 
    .ai-clist .comment-author,.ai-clist .fn{font-weight:700;font-size:14px} 
    .ai-clist .comment-meta,.ai-clist time{display:block;font-size:12px;opacity:.65;margin:2px 0 6px} 
    .ai-clist p{margin:0 0 8px;font-size:14px;line-height:1.6} 
    .ai-clist .children{list-style:none;margin:10px 0 0 16px;padding:0 0 0 12px; border-left:2px solid rgba(127,127,127,.25)} 
    .ai-creply a,.comment-reply-link{display:inline-block;font-size:12px;font-weight:600; padding:4px 10px;border:1px solid rgba(127,127,127,.35);border-radius:999px;opacity:.9} 
    .ai-creply a:hover,.comment-reply-link:hover{opacity:1;border-color:currentColor} 
    .ai-cnote{font-size:12px;opacity:.7;margin:0 0 10px} 
    .comment-form{margin:0} 
    .comment-form p{margin:0 0 10px} 
    .comment-form label{display:block;font-size:12.5px;font-weight:600;margin:0 0 4px;opacity:.85} 
    .comment-form input[type=text],.comment-form input[type=email], .comment-form input[type=url],.comment-form textarea{ width:100%;max-width:100%;box-sizing:border-box; background:rgba(127,127,127,.10);border:1px solid rgba(127,127,127,.28); border-radius:6px;padding:9px 11px;font:inherit;font-size:14px;color:inherit;outline:none} 
    .comment-form input:focus,.comment-form textarea:focus{border-color:currentColor} 
    .comment-form textarea{min-height:110px;resize:vertical} 
    .comment-form .submit,.comment-form input[type=submit]{ background:currentColor;border:0;border-radius:6px;padding:10px 20px; font-weight:700;font-size:14px;cursor:pointer; color:transparent;text-shadow:0 0 0 rgba(0,0,0,.85)} 
    .comment-form .submit:hover{filter:brightness(.92)} 
    .ai-pagi{display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin:12px 0 0} 
    .ai-pagi a,.ai-pagi span{padding:6px 12px;border-radius:6px;font-size:13px; border:1px solid rgba(127,127,127,.3)} 
    .ai-pagi .current{border-color:currentColor;font-weight:700} 
    .ai-hp{position:absolute!important;left:-9999px!important;width:1px!important; height:1px!important;overflow:hidden!important} 
    .ai-cbtn{display:inline-flex;align-items:center;justify-content:center; background:currentColor;border:0;border-radius:6px;padding:10px 20px; font-weight:700;font-size:14px;cursor:pointer; color:transparent;text-shadow:0 0 0 rgba(0,0,0,.85)} 
    .ai-cbtn:hover{filter:brightness(.92)}
    @media(max-width:520px){ .ai-panel{padding:12px} .ai-clist .children{margin-left:8px;padding-left:10px} } 
.blog-pager{display:flex;gap:9px;justify-content:center;padding:16px 0 6px;clear:both}.blog-pager a{background:var(--sl-bir2);color:#fff;font-weight:700;font-size:12.5px;padding:10px 22px;border-radius:4px}.sl-top .section,.sl-top .widget,.sl-top .header-section{margin:0!important;padding:0!important}body#layout .sl-top{position:static!important;z-index:auto!important}.sl-logo img{max-height:40px;width:auto;object-fit:contain}@media (max-width:480px){.sl-grid{grid-template-columns:repeat(2,1fr)!important;gap:10px}}iframe#comment-editor{filter:invert(.85) hue-rotate(180deg) brightness(1.1);border:none!important}.comment-thread .comment-actions{display:flex!important;flex-direction:row!important;justify-content:flex-end!important;align-items:center!important;width:100%;margin-top:10px;gap:15px}.comment-thread .comment-actions a,.comment-thread .comment-actions span{display:inline-flex!important;align-items:center!important;margin:0!important;padding:0!important;line-height:normal!important}.comment-thread li .comment-block{border:1px solid #333!important;padding:15px!important;border-radius:8px!important;margin-bottom:0!important;background-color:#1a1a1a!important}.comment-thread .avatar-image-container{margin-right:15px!important;margin-top:0!important}.comment-thread .comment-header .comment-timestamp{font-size:11px!important;opacity:.8}.comment-thread .comment-header{align-items:baseline!important}.comment-thread li{padding-bottom:0!important;margin-bottom:12px!important}.comment-thread .comment-replies{margin-top:5px!important}.sl-player.video-player-container{position:relative;width:100%;aspect-ratio:16/9;background-color:#000;border-radius:6px;overflow:hidden}.sl-player.video-player-container iframe{width:100%;height:100%;border:none;display:block}.server-dropdown{position:absolute;top:15px;right:15px;z-index:10}.server-toggle-btn{background-color:rgb(30 30 30 / .3);color:#fff;padding:8px;display:flex;align-items:center;justify-content:center;border:1px solid rgb(255 255 255 / .1);border-radius:4px;cursor:pointer;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);transition:all 0.3s ease;outline:none}.server-toggle-btn:hover,.server-dropdown.tampil .server-toggle-btn{background-color:rgb(50 50 50 / .6);border-color:rgb(255 255 255 / .3)}.server-list{display:none;position:absolute;top:100%;right:0;margin-top:8px;background-color:rgb(25 25 25 / .85);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);min-width:130px;border-radius:6px;border:1px solid rgb(255 255 255 / .1);flex-direction:column;overflow:hidden;box-shadow:0 4px 12px rgb(0 0 0 / .5);z-index:11}.server-list.tampil{display:flex!important}.server-list a{color:#ddd;padding:10px 15px;text-decoration:none;font-size:13px;text-align:left;border-bottom:1px solid rgb(255 255 255 / .05);transition:background 0.2s ease,color 0.2s ease}.server-list a:hover{background-color:rgb(255 255 255 / .1);color:#fff}.server-list a:last-child{border-bottom:none}

b:if.b:template-skin:
/* --- CSS For Layout: AnimeSail Clone --- */
body#layout,
body#layout div.section {
  font-family: Nunito, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

body#layout {
  background-color: #f8f9fa;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  text-align: left;
  max-width: 800px;
  margin: 30px auto;
  padding: 25px;
  box-shadow: 0 4px 6px rgba(0,0,0,0.05);
}

/* Badge Identitas Dasbor */
body#layout:before {
  content: "AnimeSail Clone — Tata Letak";
  display: inline-block;
  background: #209cee; /* Warna Biru Khas AnimeSail */
  color: #ffffff;
  border-radius: 5px;
  font-size: 15px;
  font-weight: 800;
  margin: 0 0 25px;
  padding: 10px 18px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* Judul Setiap Section (Header, Main, Laci, dll) */
body#layout .section h4 {
  font-size: 14px;
  text-transform: uppercase;
  margin: 0 0 10px 0;
  color: #1f1f1f;
  font-weight: 800;
}

body#layout div.section {
  background-color: transparent;
  border: none;
  max-width: 100%;
  max-height: 100%;
  padding: 0;
  margin-bottom: 24px;
}

/* Kotak Wadah Widget */
body#layout div.section > div {
  border-radius: 6px;
  overflow: hidden;
  border: 2px dashed #cbd5e1;
  background: #ffffff;
  transition: all 0.2s ease;
}

/* Efek saat area widget disorot */
body#layout div.section > div:hover {
  border-color: #209cee;
}

/* Tombol + Tambahkan Gadget */
body#layout .add_widget a {
  color: #209cee;
  font-weight: 700;
  text-decoration: none;
  display: inline-block;
  margin-top: 5px;
}

body#layout .add_widget a:hover {
  color: #0378c5; /* Biru gelap saat di-hover */
}

body#layout ul,
body#layout ol {
  list-style: none;
  margin: 0;
  padding: 0;
}

head.script:
//

class BloggerScript {
  constructor(t = {}) { this._config = t; }
  err(t) { return console.log(t), t; }

  resizeImage(t, e = !1) {
    if (!e) return t;
    let r = /\/(s|w|h)\d{1,4}-((w|s|h)(\d{1,4})+-)?(c{1,2}|p-k-no-nu|rw)/gi,
        s = /\=(s|w|h)\d{1,4}-((w|s|h)(\d{1,4})+-)?(c{1,2}|p-k-no-nu|rw)/gi,
        n = /(\/(w|h|s)\d{1,4}\/)/gi,
        i = /\=(w|h|s)\d{1,4}$/gi,
        o = /\-(rw)$/.test(e);
    return n.test(t) && (t = t.replace(n, "/s72-c/")), i.test(t) && (t = t.replace(i, "=s72-c")), o && (t = t.replace(/\.(gif|jpe?g|tiff?|png|bmp)$/, ".webp")), t.match(r) ? t.replace(r, `/${e}`) : t.match(s) ? t.replace(s, `=${e}`) : t;
  }

  getId(t) { return t.split("post-")[1]; }

  getDefault(t) {
    let e = ["published", "updated", "content", "summary", "title"], r = {};
    return e.forEach(e => { e in t && (r[e] = t[e].$t); }), r;
  }

  getImage(t) {
    let e = this._config.noImage ? this.resizeImage(this._config.noImage, this._config.sizeImage) : "";
    if ("media$thumbnail" in t) return this.resizeImage(t.media$thumbnail.url, this._config.sizeImage);
    if ("content" in t) {
      let r = t.content.$t, s = r.indexOf("<img"), n = r.indexOf('src="', s), i = r.indexOf('"', n + 5), o = r.substr(n + 5, i - n - 5);
      return -1 != s && -1 != n && -1 != i && "" != o ? o : e;
    }
    return e;
  }

  getFeed(t) {
    let e = new Array();
    if (t.feed && t.feed.entry) {
      for (let r = 0; r < t.feed.entry.length; r++) {
        const s = t.feed.entry[r];
        let n = this.getDefault(s);
        n.id = this.getId(s.id.$t);
        n.link = s.link.find(t => "alternate" == t.rel).href;
        n.image = this.getImage(s);
        n.label = s.category ? s.category.map(t => t.term) : [];
        e.push(n);
      }
    }
    return e;
  }

  async fetchFeed(url, callback) {
    try {
      let response = await fetch(url);
      let data = await response.json();
      callback(data);
    } catch (error) {
      console.error("Gagal memuat feed:", error);
      callback({});
    }
  }
}
