  document.addEventListener("DOMContentLoaded", function() {
    // Mencari semua baris anime di widget populer
    const popItems = document.querySelectorAll('.sl-baris');

    // 1. Label status/tipe yang disembunyikan
    const abaikanLabel = ["TV", "Movie", "OVA", "ONA", "Special", "Ongoing", "Completed", "Tamat", "Daftar Anime", "Donghua", "Anime", "Streaming", "Series"];

    // 2. Pola Regex untuk mendeteksi label "Eps X", "Episode X", "Eps. X"
    const regexEps = /^(eps|episode)\.?\s*(\d+)/i;

    popItems.forEach(item => {
      let genreEl = item.querySelector('.genre-populer');
      let epsEl = item.querySelector('.eps-populer');
      let postUrl = genreEl ? genreEl.getAttribute('data-url') : null;

      if(postUrl) {
        try {
          let path = new URL(postUrl).pathname;

          fetch('/feeds/posts/summary?alt=json&path=' + path)
            .then(res => res.json())
            .then(data => {
              if(data.feed && data.feed.entry && data.feed.entry[0].category) {
                let semuaLabel = data.feed.entry[0].category.map(c => c.term);

                let genreSaja = [];
                let jumlahEps = "?"; // Default jika tidak ada label Eps

                semuaLabel.forEach(label => {
                  let l = label.toLowerCase();
                  let cekEps = label.match(regexEps); // Mengecek apakah label cocok dengan pola Eps X

                  if (cekEps) {
                    // Jika cocok (misal: "Eps 100"), ambil angkanya saja yaitu "100"
                    jumlahEps = cekEps[2];
                  } else if (abaikanLabel.map(a => a.toLowerCase()).includes(l)) {
                    // Abaikan jika masuk daftar blacklist (TV, Ongoing, dll)
                  } else {
                    // Sisanya dipastikan adalah Genre
                    genreSaja.push(label);
                  }
                });

                // Cetak Genre
                if(genreEl) genreEl.innerHTML = genreSaja.length > 0 ? "Genre: " + genreSaja.join(', ') : "Genre: -";
                // Cetak Episode
                if(epsEl && jumlahEps !== "?") {
                   epsEl.innerHTML = jumlahEps + " episode tersedia";
                } else if(epsEl) {
                   epsEl.innerHTML = "Status: Berjalan"; // Teks cadangan jika tidak ada label eps
                }

              } else {
                if(genreEl) genreEl.innerHTML = "Genre: Tidak diketahui";
              }
            }).catch(e => { if(genreEl) genreEl.innerHTML = ""; });
        } catch(e) { }
      }
    });
  });
